pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warp1, uint256 warp2, uint256 roll1, uint256 roll2) public {
        amount = bound(amount, 10 ether, 10 ether);
        warp1 = bound(warp1, 1, type(uint64).max - 1);
        warp2 = bound(warp2, warp1 + 1, type(uint64).max);
        roll1 = bound(roll1, 1, type(uint64).max - 1);
        roll2 = bound(roll2, 1, type(uint64).max - 1);
        address actor = makeAddr("actor");

        vm.deal(actor, amount);
        vm.warp(warp1);
        vm.roll(roll1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amount}("");
        require(ok1, "call1 failed");

        uint256 pastAfterFirst = c.pastBlockTime();

        vm.deal(actor, amount);
        vm.warp(warp2);
        vm.roll(roll2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amount}("");
        require(ok2, "call2 failed");

        assertTrue(c.pastBlockTime() == warp2);
    }
}
